# PTX source for fp16 matrix multiplication (C = A * B.T)
PTX_SOURCE = r"""
.version 7.2
.target sm_80
.address_size 64

.visible .entry matmul_fp16(
    .param .u64 A,
    .param .u64 B,
    .param .u64 C,
    .param .u32 M,
    .param .u32 N,
    .param .u32 K
)
{
    // Load kernel parameters
    .reg .u64 %A, %B, %C;
    .reg .u32 %M, %N, %K;
    ld.param.u64 %A, [A];
    ld.param.u64 %B, [B];
    ld.param.u64 %C, [C];
    ld.param.u32 %M, [M];
    ld.param.u32 %N, [N];
    ld.param.u32 %K, [K];

    // Thread / block indices
    .reg .u32 %tid_x, %tid_y;
    .reg .u32 %blockIdx_x, %blockIdx_y;
    .reg .u32 %blockDim_x, %blockDim_y;
    mov.u32 %tid_x, %tid.x;
    mov.u32 %tid_y, %tid.y;
    mov.u32 %blockIdx_x, %ctaid.x;
    mov.u32 %blockIdx_y, %ctaid.y;
    mov.u32 %blockDim_x, %ntid.x;
    mov.u32 %blockDim_y, %ntid.y;

    // Compute global row / column indices
    .reg .u32 %row, %col;
    mul.lo.u32 %row, %blockIdx_x, %blockDim_x;
    add.u32 %row, %row, %tid_x;
    mul.lo.u32 %col, %blockIdx_y, %blockDim_y;
    add.u32 %col, %col, %tid_y;

    // Bounds check – exit if out‑of‑range
    .pred %p_exit_row, %p_exit_col;
    setp.ge.u32 %p_exit_row, %row, %M;
    @%p_exit_row ret;
    setp.ge.u32 %p_exit_col, %col, %N;
    @%p_exit_col ret;

    // Accumulator (use fp32 for precision)
    .reg .f32 %sum;
    mov.f32 %sum, 0f0;

    // Loop over K dimension
    .reg .u32 %k;
    mov.u32 %k, 0;

LOOP:
    setp.ge.u32 %p_end, %k, %K;
    @%p_end bra DONE;

    // ---- Load A[row, k] ----
    .reg .u32 %idxA;
    mul.lo.u32 %idxA, %row, %K;
    add.u32 %idxA, %idxA, %k;               // linear index for A

    .reg .u64 %addrA;
    mul.wide.u32 %addrA, %idxA, 2;          // each fp16 = 2 bytes
    add.u64 %addrA, %A, %addrA;

    .reg .f16 %a_f16;
    ld.global.f16 %a_f16, [%addrA];

    // ---- Load B[col, k] (B is stored as (N, K), we treat col as row of B^T) ----
    .reg .u32 %idxB;
    mul.lo.u32 %idxB, %col, %K;
    add.u32 %idxB, %idxB, %k;               // linear index for B

    .reg .u64 %addrB;
    mul.wide.u32 %addrB, %idxB, 2;
    add.u64 %addrB, %B, %addrB;

    .reg .f16 %b_f16;
    ld.global.f16 %b_f16, [%addrB];

    // Convert to fp32
    .reg .f32 %a_f32, %b_f32;
    cvt.f32.f16 %a_f32, %a_f16;
    cvt.f32.f16 %b_f32, %b_f16;

    // FMA: sum += a * b
    fma.rn.f32 %sum, %a_f32, %b_f32, %sum;

    // Increment k
    add.u32 %k, %k, 1;
    bra LOOP;

DONE:
    // Convert accumulator back to fp16
    .reg .f16 %c_f16;
    cvt.rn.f16.f32 %c_f16, %sum;

    // Compute output index C[row, col]
    .reg .u32 %idxC;
    mul.lo.u32 %idxC, %row, %N;
    add.u32 %idxC, %idxC, %col;

    .reg .u64 %addrC;
    mul.wide.u32 %addrC, %idxC, 2;
    add.u64 %addrC, %C, %addrC;

    // Store result
    st.global.f16 [%addrC], %c_f16;

    ret;
}
"""

class ModelNew:
    def __init__(self):
        # Load the PTX module using the harness API
        self.module = ptx_load(PTX_SOURCE)

    def __call__(self, A, B):
        """
        A: torch.Tensor of shape (M, K), dtype torch.float16, device='cuda'
        B: torch.Tensor of shape (N, K), dtype torch.float16, device='cuda'
        Returns C = A @ B.T, shape (M, N), dtype torch.float16
        """
        assert A.is_cuda and B.is_cuda
        assert A.dtype == torch.float16 and B.dtype == torch.float16
        M, K = A.shape
        N, Kb = B.shape
        assert K == Kb

        C = torch.empty(M, N, dtype=torch.float16, device='cuda')

        # Launch configuration: 16x16 threads per block
        block = (16, 16, 1)
        grid = ((M + block[0] - 1) // block[0],
                (N + block[1] - 1) // block[1],
                1)

        args = [
            A.data_ptr(),
            B.data_ptr(),
            C.data_ptr(),
            M,
            N,
            K
        ]

        ptx_launch(self.module, "matmul_fp16", grid, block, args)
        return C
